        function randomInt(limit: number): number {
            return Math.floor(Math.random() * limit);
        }
        function reload() {
            let newTip = randomInt(tips.length);
            if (recentTips.length >= 20) { // create a buffer of 20 tips recent so that we don't get the same tip too often
                recentTips.pop();
            }
            if (recentTips.includes(newTip)) {
                reload();
                return;
            } else {
                recentTips.push(newTip);
                DOM.tipDiv.innerHTML = tips.at(newTip)!;
            }
        }
